using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B1DeskInspect {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B1_DeskPropRefinement/";static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B1_Circular.unity"))throw new Exception("Saved B1 required");Directory.CreateDirectory(H);if(File.Exists(H+"before.json"))throw new Exception("Do not overwrite baseline");var root=GameObject.Find("B1_ResearchAndStaffFloor");var layout=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B1_InteriorRedesign/layout.json"));
 var props=new List<object>();var names=new HashSet<string>{"BL_ResearchDesk","SF_SC_OperatorDesk_A","SF_SC_OperatorDesk_B","SF_SC_IncidentReview","SF_SC_RadioDutyStation","SF_BriefingTable","BL_ConferenceTable","BL_DiningSet","SF_VitalCart","SF_UltrasoundCart","BL_ServingCounter","SF_MealPreparation","BL_HandheldRecorder"};Directory.CreateDirectory(H+"mesh_export");var seen=new HashSet<string>();
 foreach(var q in layout["placements"].Where(q=>names.Contains((string)q["model"]))){var t=root.transform.Find("B1_"+(string)q["room"]+"_Sector/Equipment/"+(string)q["name"]);var renderers=t.GetComponentsInChildren<MeshRenderer>(true);props.Add(new{name=t.name,room=(string)q["room"],model=(string)q["model"],path=P(t),world=V(t.position),rotation=V(t.eulerAngles),scale=V(t.localScale),meshes=renderers.Select(rr=>{var mf=rr.GetComponent<MeshFilter>();return new{path=P(rr.transform),asset=AssetDatabase.GetAssetPath(mf.sharedMesh),mesh=mf.sharedMesh.name,position=V(rr.transform.localPosition),rotation=V(rr.transform.localEulerAngles),scale=V(rr.transform.localScale),materials=rr.sharedMaterials.Select(AssetDatabase.GetAssetPath),bounds=new{center=V(rr.bounds.center),size=V(rr.bounds.size)}};})});
 if(seen.Add((string)q["model"])){var fs=t.GetComponentsInChildren<MeshFilter>(true);var meshes=fs.Select(f=>{var m=f.sharedMesh;var rr=f.GetComponent<Renderer>();var matrix=t.worldToLocalMatrix*f.transform.localToWorldMatrix;return new{name=m.name,path=P(f.transform),vertices=m.vertices.Select(v=>V(matrix.MultiplyPoint3x4(v))),normals=m.normals.Select(n=>V(matrix.MultiplyVector(n).normalized)),uv=m.uv.Select(u=>new[]{u.x,u.y}),materials=rr.sharedMaterials.Select(AssetDatabase.GetAssetPath),submeshes=Enumerable.Range(0,m.subMeshCount).Select(m.GetTriangles)};});File.WriteAllText(H+"mesh_export/"+(string)q["model"]+".json",JsonConvert.SerializeObject(meshes));}}
 var result=new{scene=s.path,props,transforms=root.GetComponentsInChildren<Transform>(true).Select(t=>new{path=P(t),pos=V(t.localPosition),rot=V(t.localEulerAngles),scale=V(t.localScale),active=t.gameObject.activeSelf}),colliders=root.GetComponentsInChildren<Collider>(true).Select(c=>new{path=P(c.transform),type=c.GetType().Name,c.enabled,center=V(c.bounds.center),size=V(c.bounds.size)}),lights=root.GetComponentsInChildren<Light>(true).Select(l=>new{path=P(l.transform),l.enabled,l.intensity,l.range,color=new[]{l.color.r,l.color.g,l.color.b},shadow=l.shadows.ToString()} )};File.WriteAllText(H+"before.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{props=props.Count,models=seen.Count,objects=root.GetComponentsInChildren<Transform>(true).Length};}
}
